package com.estoqueinteligente.alert;
import com.estoqueinteligente.product.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class AlertService{private final ProductService products;public AlertService(ProductService p){products=p;}public List<ProductResponse> lowStock(){return products.findByCurrentStatus(ProductStatus.SALDO_NEGATIVO);}public List<ProductResponse> expiring(){return products.findByCurrentStatus(ProductStatus.VENCENDO);}public List<ProductResponse> expired(){return products.findByCurrentStatus(ProductStatus.VENCIDO);}public AlertSummaryResponse summary(){return new AlertSummaryResponse(lowStock().size(),expiring().size(),expired().size());}}
